def spiral2(seed,H,W,inp,wrap):
    cells=set(); order=[]
    r,c=seed; L=2; dirs=[(-1,0),(0,1),(1,0),(0,-1)]
    cells.add(seed); order.append(seed)
    for k in range(30):
        dr,dc=dirs[k%4]
        for _ in range(L):
            r=(r+dr)%H if wrap else r+dr
            c=(c+dc)%W if wrap else c+dc
            if not(0<=r<H and 0<=c<W): return cells
            if inp[r][c]==2 or (r,c) in cells: return cells
            cells.add((r,c)); order.append((r,c))
        if k%2==1: L+=2
    return cells

