def transform(g):
    H,W=len(g),len(g[0])
    seed=next((i,j) for i in range(H) for j in range(W) if g[i][j]==3)
    out=[row[:] for row in g]
    sr,sc=seed; L=2; dirs=[(-1,0),(0,1),(1,0),(0,-1)]
    cells={seed}
    r,c=sr,sc
    for k in range(40):
        dr,dc=dirs[k%4]
        for _ in range(L):
            nr,nc=r+dr,c+dc
            mc=nc%W
            if nr<0: mr=-nr+(H-2)
            elif nr>=H: mr=(H-1)-(nr-(H-1))
            else: mr=nr
            if not(0<=mr<H and 0<=mc<W):
                break            # arm ends; spiral continues from current cell
            if g[mr][mc]==2 or (mr,mc) in cells:
                return out       # spiral terminates
            cells.add((mr,mc)); out[mr][mc]=3
            r,c=nr,nc
        if k%2==1: L+=2
    return out

